// Statement-picker permutation coverage for workspace 55390, generated.
//
// This used to be a 38,659-line committed JSON file. Nothing in it was ever
// captured: every one of its 1,620 service and budget rows was formula output
// from a loop someone ran once, against a hardcoded 2022-2026 year range that
// had to be regenerated by hand each time the picker's window moved. The loop
// is the artefact worth keeping, so it lives here and the JSON is gone.
//
// What it produces, and why:
//
//   - one delivered service row per (board, participant, picker year, month),
//     so every Participant x Month x Year combination the Monthly Statement
//     picker offers loads a non-empty statement on all three Care Management
//     boards;
//   - one budget row per SaH participant x standard stream x month, so the
//     Budget Mini Charts and every Individualised Budgets stream render with
//     real numbers for any picked month;
//   - the profiles, service plans and funding sources those rows reference,
//     so the fixture is self-contained and composable with either 55390
//     fixture (ids are disjoint — everything here carries the `55390e00-`
//     prefix).
//
// Amounts vary deterministically per permutation so a statement is legible
// rather than a column of identical numbers; the split is 90/10 government /
// participant. Nothing here reads the clock except the DEFAULT year range,
// which is the picker's own window (currentYear-4 … currentYear) — pass
// `years` explicitly for a byte-stable result.
//
// folderIds ARE folder names: offline mode serves board folders derived from
// item folderIds (`getFolderOffline`, name === id), so the folder-filtered
// statement and invoice-generator routes behave like live ISO+. Do not rename
// them. No row carries `Timesheet Approval`, so no invoice path can ever bill
// these rows, though they do share the invoice lists via the service folder
// exactly as a live shift row would.
//
// Pure: no I/O, no randomness, no mutation of its arguments. Loaded by
// `scripts/dev-fixture.mjs --file test/fixtures/generators/statementPermutations.mjs`
// and asserted by `test/unit/fixtures/careManagementStatementPermutations.test.js`.

export const WORKSPACE_ID = '55390';

export const SAH_BOARD = 'jpjztrn14pJ';
export const NDIS_BOARD = 'o24sGM1FoST';
export const NEW_BOARD = 'dwV23F5WcQL';
export const LIBRARY_BOARD = 't29GNU4nV2A';

export const SERVICE_FOLDER = 'Shift Planning and Reporting';
export const PROFILE_FOLDER = '📋 Participants Intake';
export const REFERENCE_FOLDER = 'stmt-perm-refs';

// Board id → participants, in the order the profiles are numbered. Adding a
// participant here adds a full year x month sweep of rows for them.
export const BOARD_PARTICIPANTS = {
    [SAH_BOARD]: ['Jane Smith', 'David Brown', 'Lisa Morphy'],
    [NDIS_BOARD]: ['David Smith', 'Martin Space', 'Sunil Patel', 'George Brown', 'Kate Abraham'],
    [NEW_BOARD]: ['Mike Bird']
};

// The four funding streams the SaH statement summarises against.
const FUNDING_STREAMS = [
    'Home Support(HS) Quarterly',
    'Restorative Care Pathway',
    'Assistive Technology - Short-term',
    'Home Modification'
];

// Service plans, in the order they are numbered. `Service ID/Item ID` is the
// attribute the SaH route falls back to; `Service Plan ID` is deliberately
// absent, matching dev.
const SERVICE_PLANS = [
    { service: 'Assistance with self-care and activities of daily living', code: 'SERV-0020' },
    { service: 'General house cleaning', code: 'SERV-0001' },
    { service: 'Registered nurse clinical care', code: 'SERV-0023' },
    { service: 'Physiotherapy', code: 'SERV-0034' },
    { service: 'Meal preparation', code: 'SERV-0008' },
    { service: 'Social Work', code: 'SERV-0029' }
];

// The six Individualised Budgets streams. folderName is the folder the route
// filters on; base is the stream's floor before the per-permutation variation.
const BUDGET_STREAMS = [
    { folderName: 'Home Support Quarterly Budget', classification: 'Home Support Quarterly', base: 5000 },
    { folderName: 'Assistive Technology - Short-term Budget', classification: 'Assistive Technology - Short-term', base: 2500 },
    { folderName: 'Assistive Technology - Ongoing Budget', classification: 'Assistive Technology - Ongoing', base: 1800 },
    { folderName: 'Home Modification Budget', classification: 'Home Modification', base: 4000 },
    { folderName: 'Restorative Care Pathway Budget', classification: 'Restorative Care Pathway', base: 3200 },
    { folderName: 'End-of-Life Pathway Budget', classification: 'End-of-Life Pathway', base: 2000 }
];

// Hardcoded rather than toLocaleString: the fixture must not vary with the
// machine's ICU data or default locale.
const MONTH_NAMES = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'
];

const MONTHS = Array.from({ length: 12 }, (_, i) => i + 1);

// Quantities cycle so a month's statement is not twelve identical lines.
const QUANTITIES = [1.5, 2, 1];

const GOVERNMENT_SHARE = 0.9;
const AVAILABLE_FUND_SHARE = 0.8;
const PREVIOUS_SPENDING_SHARE = 0.1;

// Id groups. The digit is repeated into both UUID fields, which is what makes
// an id readable at a glance: -4001-8001- is a profile, -4003-8003- is a row.
const GROUP = { profile: 1, servicePlan: 2, row: 3, fundingSource: 4 };

const uuid = (group, serial) =>
    `55390e00-0000-400${group}-800${group}-${String(serial).padStart(12, '0')}`;

const round2 = (value) => Math.round(value * 100) / 100;

const pad2 = (value) => String(value).padStart(2, '0');

/**
 * The years the Monthly Statement picker offers: the current year and the four
 * before it. Defaulting to this is what retires the manual regeneration chore
 * the JSON carried.
 */
export const pickerYears = (currentYear = new Date().getFullYear()) =>
    Array.from({ length: 5 }, (_, i) => currentYear - 4 + i);

// --- reference items ---------------------------------------------------------

// Funding sources and service plans share one serial run (1-4, then 5-10) and
// live on dev's real NDIS Library board, in a folder no list filter matches.
const buildFundingSources = () => FUNDING_STREAMS.map((stream, i) => ({
    $case: `funding source — ${stream}`,
    itemId: uuid(GROUP.fundingSource, i + 1),
    boardId: LIBRARY_BOARD,
    folderId: REFERENCE_FOLDER,
    data: { 'Funding Stream': stream }
}));

const buildServicePlans = () => SERVICE_PLANS.map((plan, i) => ({
    $case: `service plan — ${plan.service}`,
    itemId: uuid(GROUP.servicePlan, FUNDING_STREAMS.length + i + 1),
    boardId: LIBRARY_BOARD,
    folderId: REFERENCE_FOLDER,
    data: { Service: plan.service, 'Service ID/Item ID': plan.code }
}));

/**
 * One profile per participant, numbered across boards in declaration order.
 * Returns the items plus a boardId → [{ name, itemId }] index the row builders
 * need, so the numbering is decided in exactly one place.
 */
const buildProfiles = (boardParticipants) => {
    const items = [];
    const index = {};
    for (const [boardId, participants] of Object.entries(boardParticipants)) {
        index[boardId] = participants.map((name) => {
            const serial = items.length + 1;
            const itemId = uuid(GROUP.profile, serial);
            items.push({
                $case: `statement profile — ${name}`,
                itemId,
                boardId,
                folderId: PROFILE_FOLDER,
                data: {
                    'Full Name/Preferred Name': name,
                    'Billing Contact': name,
                    'Billing Address': `${serial} Permutation Way, Demoville NSW 2001`
                }
            });
            return { name, itemId };
        });
    }
    return { items, index };
};

// --- service rows ------------------------------------------------------------

/**
 * The money on one permutation. `participantIndex` is the position within the
 * board and `yearIndex` the position within the requested year range, so every
 * (participant, year, month) triple gets a distinguishable but reproducible
 * amount.
 */
const serviceAmounts = ({ participantIndex, yearIndex, month }) => {
    const unitPrice = 80 + (2 * month) + (3 * participantIndex) + (5 * yearIndex);
    const quantity = QUANTITIES[(participantIndex + month - 1) % QUANTITIES.length];
    const total = round2(unitPrice * quantity);
    const government = round2(total * GOVERNMENT_SHARE);
    return {
        unitPrice,
        quantity,
        total,
        government,
        participant: round2(total - government)
    };
};

const buildServiceRow = ({ boardId, profileId, participantIndex, year, yearIndex, month, serial }) => {
    const { unitPrice, quantity, total, government, participant } =
        serviceAmounts({ participantIndex, yearIndex, month });
    const day = `${year}-${pad2(month)}-10`;
    return {
        itemId: uuid(GROUP.row, serial),
        boardId,
        folderId: SERVICE_FOLDER,
        data: {
            'Participant Profile': [profileId],
            'Service Plan': [uuid(
                GROUP.servicePlan,
                FUNDING_STREAMS.length + ((participantIndex + month) % SERVICE_PLANS.length) + 1
            )],
            'Funding Source': [uuid(
                GROUP.fundingSource,
                ((participantIndex + month) % FUNDING_STREAMS.length) + 1
            )],
            'Scheduled Shift Start Date & Time': `${day}T10:00:00+10:00`,
            'Actual Shift End Date & Time': `${day}T11:30:00+10:00`,
            'Transaction Status': 'Delivered - To be claimed and invoiced.',
            'Delivered by': '👥 Company Workforce',
            'Service Provider': 'ISO Consulting Services',
            Unit: 'Hours',
            Quantity: quantity,
            'Unit Price ($)': unitPrice,
            'Total Amount ($)': total,
            'Government Subsidy ($)': government,
            'Participant Contribution ($)': participant
        }
    };
};

const buildServiceRows = ({ profileIndex, years, nextSerial }) => {
    const rows = [];
    for (const [boardId, profiles] of Object.entries(profileIndex)) {
        profiles.forEach(({ itemId }, participantIndex) => {
            years.forEach((year, yearIndex) => {
                for (const month of MONTHS) {
                    rows.push(buildServiceRow({
                        boardId,
                        profileId: itemId,
                        participantIndex,
                        year,
                        yearIndex,
                        month,
                        serial: nextSerial + rows.length
                    }));
                }
            });
        });
    }
    return rows;
};

// --- budget rows -------------------------------------------------------------

const buildBudgetRow = ({ boardId, profileId, stream, year, yearIndex, month, serial }) => {
    const quarterlyBudget = stream.base + (10 * month) + (25 * yearIndex);
    return {
        itemId: uuid(GROUP.row, serial),
        boardId,
        folderId: stream.folderName,
        data: {
            'Participant Profile': [profileId],
            Month: MONTH_NAMES[month - 1],
            Year: String(year),
            'FY Quarter': `Q${Math.ceil(month / 3)}`,
            'Fund Classification': stream.classification,
            'Quarterly Budget ($)': quarterlyBudget,
            'Fund Amount ($)': quarterlyBudget,
            'Available Fund at the Start of the Month ($)': round2(quarterlyBudget * AVAILABLE_FUND_SHARE),
            'Carryover Funding from the Previous Quarter ($)': 0,
            'Spending from Previous Month(s) within same Quarter ($)': round2(quarterlyBudget * PREVIOUS_SPENDING_SHARE),
            'Spending from Previous Month(s) within Allocated Period ($)': round2(quarterlyBudget * PREVIOUS_SPENDING_SHARE),
            'Funding Start Date': `${year}-01-01`,
            'Funding End Date': `${year}-12-31`
        }
    };
};

// Budgets are a SaH concept, so only the SaH board's participants get them.
const buildBudgetRows = ({ profileIndex, years, nextSerial, budgetBoardId }) => {
    const rows = [];
    for (const { itemId } of profileIndex[budgetBoardId] ?? []) {
        years.forEach((year, yearIndex) => {
            for (const month of MONTHS) {
                for (const stream of BUDGET_STREAMS) {
                    rows.push(buildBudgetRow({
                        boardId: budgetBoardId,
                        profileId: itemId,
                        stream,
                        year,
                        yearIndex,
                        month,
                        serial: nextSerial + rows.length
                    }));
                }
            }
        });
    }
    return rows;
};

// --- the items ---------------------------------------------------------------

/**
 * Every item the fixture holds, in load order: references, profiles, service
 * rows, budget rows.
 *
 * @param {object} [options]
 * @param {number[]} [options.years] year range; defaults to the picker's window
 * @param {Record<string, string[]>} [options.boardParticipants] board → names
 * @param {string} [options.budgetBoardId] board whose participants get budgets
 */
export function buildStatementPermutations({
    years = pickerYears(),
    boardParticipants = BOARD_PARTICIPANTS,
    budgetBoardId = SAH_BOARD
} = {}) {
    const references = [...buildFundingSources(), ...buildServicePlans()];
    const { items: profiles, index: profileIndex } = buildProfiles(boardParticipants);

    // Rows continue the reference items' serial run, which is why the first
    // service row is 11 rather than 1.
    const serviceRows = buildServiceRows({
        profileIndex, years, nextSerial: references.length + 1
    });
    const budgetRows = buildBudgetRows({
        profileIndex,
        years,
        nextSerial: references.length + serviceRows.length + 1,
        budgetBoardId
    });

    return [...references, ...profiles, ...serviceRows, ...budgetRows];
}

