/**
 * The whole fixture in the shape `scripts/dev-fixture.mjs` loads — business,
 * boards, items. Data only: no automationSettings, no scheduledJobs, no
 * invoiceNumbers, so loading it can never arm a scheduler tick.
 */
export function buildStatementPermutationsFixture(options = {}) {
    return {
        $description: [
            'Statement-picker permutation coverage for workspace 55390, generated by',
            'test/fixtures/generators/statementPermutations.mjs: one delivered service',
            'row per (board, participant, picker year, month) plus one budget row per',
            'SaH participant x standard stream x month, so every Monthly Statement',
            'Generator combination loads a populated statement — services, summary,',
            'and all six Individualised Budgets streams.'
        ],
        business: BUSINESS,
        boards: BOARDS,
        items: buildStatementPermutations(options)
    };
}

export default buildStatementPermutationsFixture;
